#!/usr/bin/env python3
"""Validate the pair files and manifest generated by prepare_fever_pairs.py."""
from __future__ import annotations

import argparse
import json
import sys
from collections import Counter
from pathlib import Path
from typing import Any, Dict, Set

REQUIRED_FIELDS = {
    "pair_id", "claim_id", "claim_text", "passage_text", "relevance_label",
    "stance_label", "claim_level_label", "split", "passage_source",
    "wiki_page_ids", "wiki_sentence_ids", "evidence_group_ids", "label_origin",
    "is_synthetic_label",
}
VALID_RELEVANCE = {"relevant", "irrelevant"}
VALID_STANCE = {"supports", "contradicts"}
VALID_CLAIM_LABEL = {"SUPPORTS", "REFUTES", "NOT ENOUGH INFO"}


def validate_split(path: Path, expected_split: str) -> Dict[str, Any]:
    if not path.is_file():
        raise ValueError(f"Missing pair file: {path}")
    counts = Counter()
    seen_ids: Set[str] = set()
    with path.open("r", encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, 1):
            if not line.strip():
                continue
            try:
                row = json.loads(line)
            except json.JSONDecodeError as exc:
                raise ValueError(f"Invalid JSON at {path}:{line_number}: {exc}") from exc
            missing = REQUIRED_FIELDS - set(row)
            if missing:
                raise ValueError(f"{path}:{line_number}: missing fields {sorted(missing)}")
            if row["split"] != expected_split:
                raise ValueError(f"{path}:{line_number}: split={row['split']!r}, expected {expected_split!r}")
            if row["relevance_label"] not in VALID_RELEVANCE:
                raise ValueError(f"{path}:{line_number}: invalid relevance_label")
            stance = row["stance_label"]
            if stance is not None and stance not in VALID_STANCE:
                raise ValueError(f"{path}:{line_number}: invalid stance_label")
            if row["claim_level_label"] not in VALID_CLAIM_LABEL:
                raise ValueError(f"{path}:{line_number}: invalid claim_level_label")
            if not str(row["claim_text"]).strip() or not str(row["passage_text"]).strip():
                raise ValueError(f"{path}:{line_number}: empty claim or passage")
            page_ids = row["wiki_page_ids"]
            sentence_ids = row["wiki_sentence_ids"]
            if (not isinstance(page_ids, list) or not page_ids or
                    not isinstance(sentence_ids, list) or not sentence_ids or
                    len(page_ids) != len(sentence_ids) or
                    any(not isinstance(page_id, str) or not page_id for page_id in page_ids) or
                    any(not isinstance(sentence_id, int) for sentence_id in sentence_ids)):
                raise ValueError(f"{path}:{line_number}: invalid Wikipedia page/sentence locators")
            if not isinstance(row["evidence_group_ids"], list) or any(not isinstance(x, int) for x in row["evidence_group_ids"]):
                raise ValueError(f"{path}:{line_number}: invalid evidence_group_ids")
            if not isinstance(row["pair_id"], str) or not row["pair_id"]:
                raise ValueError(f"{path}:{line_number}: invalid pair_id")
            if row["passage_source"] != "FEVER_WIKIPEDIA":
                raise ValueError(f"{path}:{line_number}: unexpected passage_source")
            if row["pair_id"] in seen_ids:
                raise ValueError(f"{path}:{line_number}: duplicate pair_id {row['pair_id']}")
            seen_ids.add(row["pair_id"])

            origin = row["label_origin"]
            if origin == "fever_gold_evidence":
                if row["is_synthetic_label"] is not False:
                    raise ValueError(f"{path}:{line_number}: gold pair incorrectly marked synthetic")
                if row["relevance_label"] != "relevant" or row["stance_label"] not in {"supports", "contradicts"}:
                    raise ValueError(f"{path}:{line_number}: invalid gold-evidence label combination")
                expected_claim_label = "SUPPORTS" if row["stance_label"] == "supports" else "REFUTES"
                if row["claim_level_label"] != expected_claim_label or not row["evidence_group_ids"]:
                    raise ValueError(f"{path}:{line_number}: gold pair has inconsistent claim label or no evidence group")
            elif origin == "synthetic_random_negative":
                if row["is_synthetic_label"] is not True:
                    raise ValueError(f"{path}:{line_number}: synthetic pair not marked synthetic")
                if row["relevance_label"] != "irrelevant" or row["stance_label"] is not None:
                    raise ValueError(f"{path}:{line_number}: synthetic negatives must be irrelevant with null stance")
                if row["evidence_group_ids"]:
                    raise ValueError(f"{path}:{line_number}: synthetic negative must not claim a FEVER evidence group")
            else:
                raise ValueError(f"{path}:{line_number}: unknown label_origin {origin!r}")

            counts["pairs_total"] += 1
            counts[f"relevance_{row['relevance_label']}"] += 1
            if row["stance_label"] is None:
                counts["stance_unlabelled_synthetic_pairs"] += 1
            else:
                counts[f"stance_{row['stance_label']}"] += 1
            counts["gold_evidence_pairs" if origin == "fever_gold_evidence" else "synthetic_negative_pairs"] += 1
    return {key: int(value) for key, value in sorted(counts.items())}


def synthetic_locator_set(path: Path) -> Set[tuple[str, int]]:
    """Return synthetic-negative page/sentence locators for split-leakage checks."""
    locators: Set[tuple[str, int]] = set()
    with path.open("r", encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, 1):
            if not line.strip():
                continue
            row = json.loads(line)
            if row.get("label_origin") == "synthetic_random_negative":
                for page_id, sentence_id in zip(row["wiki_page_ids"], row["wiki_sentence_ids"]):
                    locators.add((page_id, sentence_id))
    return locators


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input-dir", type=Path, default=Path("data/fever/processed_pairs"))
    args = parser.parse_args()
    input_dir = args.input_dir.expanduser().resolve()
    manifest_path = input_dir / "dataset_manifest.json"
    if not manifest_path.is_file():
        print(f"ERROR: missing manifest: {manifest_path}", file=sys.stderr)
        return 2
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        if manifest.get("dataset") != "FEVER v1.0":
            raise ValueError("manifest dataset is not FEVER v1.0")
        if manifest.get("preparation_version") != 2:
            raise ValueError("dataset was not generated by preparation version 2; regenerate it")
        if not (input_dir / "missing_evidence.jsonl").is_file():
            raise ValueError("missing_evidence.jsonl is missing")
        results = {
            "train": validate_split(input_dir / "train_pairs.jsonl", "train"),
            "validation": validate_split(input_dir / "validation_pairs.jsonl", "validation"),
        }
        train_negatives = synthetic_locator_set(input_dir / "train_pairs.jsonl")
        validation_negatives = synthetic_locator_set(input_dir / "validation_pairs.jsonl")
        overlap = train_negatives & validation_negatives
        if overlap:
            example = sorted(overlap)[0]
            raise ValueError(f"synthetic negative passage leakage across splits; example locator: {example}")
        count_keys = {
            "pairs_total", "relevance_relevant", "relevance_irrelevant",
            "stance_supports", "stance_contradicts", "stance_unlabelled_synthetic_pairs",
            "gold_evidence_pairs", "synthetic_negative_pairs",
        }
        for split, actual in results.items():
            expected = manifest.get("pair_counts", {}).get(split, {})
            for key in count_keys:
                expected_value = int(expected.get(key, 0))
                actual_value = int(actual.get(key, 0))
                if expected_value != actual_value:
                    raise ValueError(f"{split}: manifest mismatch for {key}: {expected_value} != {actual_value}")
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        print(f"VALIDATION FAILED: {exc}", file=sys.stderr)
        return 1
    print("VALIDATION PASSED")
    for split, counts in results.items():
        print(f"{split}: {counts.get('pairs_total', 0):,} pairs; "
              f"{counts.get('gold_evidence_pairs', 0):,} gold; "
              f"{counts.get('synthetic_negative_pairs', 0):,} synthetic negatives")
    print("Synthetic negative page/sentence locators are disjoint across splits.")
    print("Note: the validator checks structure and label provenance, not model quality.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
